// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(uint256 callerSeed) public {
        address caller = address(uint160(callerSeed));
        vm.prank(caller);
        string memory ver = c.version();
        assertTrue(keccak256(abi.encodePacked(ver)) == keccak256(abi.encodePacked("1.0.0")));
    }
}
